  const art = document.querySelector('article');
  const lines = art.innerText.split('\n').map(l=>l.trim());
  // achar 2a ocorrência de acirvoficial e parar antes da data (linha que é só data '12 de agosto' etc)
  const idxs = lines.map((l,i)=>l==='acirvoficial'?i:-1).filter(i=>i>=0);
  const start = idxs.length>=2 ? idxs[1]+1 : (idxs[0]+1);
  let end = lines.length;
  for (let i=start;i<lines.length;i++) {
    if (/^\d{1,2} de \w+$/.test(lines[i]) || /^Há \d+/.test(lines[i])) { end=i; break; }
  }
  const legenda = lines.slice(start, end).join('\n').trim();
  return JSON.stringify({legenda});
})()"}

